622		}
623		if len(p.Children) != 1 || p.Children[0] != "C" {
624			t.Fatalf("父样来源/子样关系应保留: %+v", p.Children)
625		}
626		if c.ParentID != "P" || c.InitialQty != "3.250" || c.Remaining != "0.000" ||
627			c.Destruction == nil || c.Destruction.Qty != "3.250" ||
628			c.Destruction.Reason != "子样销毁" || !c.Destruction.At.Equal(childAt) {
629			t.Fatalf("子样销毁记录恢复错误: %+v", c)
630		}
631	
632		// 恢复后销毁幂等与操作限制继续生效。
633		if _, err := s2.Destroy(DestroyInput{
634			SampleID: "P", Operator: "张三", Location: "A", At: parentAt, Reason: "原样销毁",
635		}); err != nil {
636			t.Fatalf("恢复后相同销毁请求应幂等返回: %v", err)
637		}
638		if _, err := s2.Split(SplitInput{ParentID: "P", Parts: []SplitPart{{ID: "X", Qty: "0.001"}}}); !errors.Is(err, ErrConflict) {
639			t.Fatalf("恢复后已销毁父样仍不得分装, got %v", err)
640		}
641		if _, err := s2.Handover(HandoverInput{
642			TransferID: "T-X", SampleID: "C",
643			FromHolder: "张三", FromLocation: "A",
644			ToHolder: "李四", ToLocation: "B", HandedOverAt: childAt.Add(time.Hour),
645		}); !errors.Is(err, ErrConflict) {
646			t.Fatalf("恢复后已销毁子样仍不得发起交接, got %v", err)
647		}
648	
649		// 原始文件没有被恢复流程改写（仍为最后一次成功操作落盘的内容，
650		// 重新打开前后再次读取一致）。
651		raw, err := os.ReadFile(path)
652		if err != nil {
653			t.Fatal(err)
654		}
655		if !strings.Contains(string(raw), `"qty": 6750`) || !strings.Contains(string(raw), `"qty": 3250`) {
656			t.Fatalf("落盘文件应原样保留两份销毁量: %s", string(raw))
657		}
658	}
