      {"kind":"transfer-in","time":"2026-10-02T11:00:00Z","holder":"李四","location":"实验室B","detail":"交接 TR-001 确认接收（交出时间 2026-10-02T10:00:00Z）"},
      {"kind":"split","time":"2026-10-02T12:00:00Z","holder":"李四","location":"实验室B","detail":"分装创建子样 S-001-A"},
