//	s.Confirm(custody.ConfirmInput{TransferID: "TR-001", Receiver: "李四", AtLocation: "实验室B", ReceivedAt: receiveTime})
//	// 销毁样品当时的全部剩余量（不接受部分销毁，成功后返回最新查询结果）
